        {
            var combat = m.GetComponent<EnemyCombatComponent>();
            if (combat != null) combat.OnAttackPerformed -= TryHealFromMinionHit;
        }
        catch (MissingReferenceException) { }
        Destroy(m);
    }
    summonedMinions.Clear();
}

